import{_ as a,a as r,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"Go 基础复习：用实验回答切片、接口、取消与事务问题","description":"先独立回答，再沿共用正文验证结果；记录解释、边界和项目证据，避免只背面试结论。","frontmatter":{"title":"Go 基础复习：用实验回答切片、接口、取消与事务问题","description":"先独立回答，再沿共用正文验证结果；记录解释、边界和项目证据，避免只背面试结论。","showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","summary":"先独立回答，再沿共用正文验证结果；记录解释、边界和项目证据，避免只背面试结论。","status":"active","related":[{"title":"Beego 工程维护：模块、MVC 与排错","link":"/programming/go/plus/ecosystem/base-beego","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 编码规范：格式、命名、接口与评审","link":"/programming/go/plus/practice/coding_guidelines","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 标准库：文件、JSON 与时间","link":"/programming/go/plus/stdlib/stdlib","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 定时任务：Timer、Ticker、cron 与退出","link":"/programming/go/plus/practice/scheduling","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 反射：检查类型、字段与可修改性","link":"/programming/go/base/advanced/reflection","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"programming/go/pro/review/review.md","filePath":"programming/go/pro/review/review.md"}'),o={name:"programming/go/pro/review/review.md"};function t(s,e,l,c,p,g){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="go-基础复习-用实验回答切片、接口、取消与事务问题" tabindex="-1">Go 基础复习：用实验回答切片、接口、取消与事务问题 <a class="header-anchor" href="#go-基础复习-用实验回答切片、接口、取消与事务问题" aria-label="Permalink to &quot;Go 基础复习：用实验回答切片、接口、取消与事务问题&quot;">​</a></h1><p>适合已经走完基础路线、需要巩固或面试前自测的读者。本文不复制整套示例：先遮住答案回答，再到链接中的完整程序运行验证。示例环境沿用 Go 1.27.2，Windows/Linux 的验证属于历史记录，本轮只复核答案与对应源码，未执行示例；macOS 仅作平台说明，本项目不执行平台运行验证。此页覆盖首批能力，不代表完整高级面试课程。</p><h2 id="slice-review" tabindex="-1">切片复制是否独立 <a class="header-anchor" href="#slice-review" aria-label="Permalink to &quot;切片复制是否独立 {#slice-review}&quot;">​</a></h2><p>题目：把一个切片赋给另一个变量后，修改第二个切片的元素，第一个是否受影响？append 后又如何？不要只答“引用类型”，要解释容量和底层数组。用<a href="/programming/go/base/basic/values#slice">切片的完整实验</a>预测每行输出，再运行核对。</p><details class="details custom-block"><summary>参考解法</summary><p>赋值复制切片描述信息，两个切片可能共享底层数组；修改共享元素会相互影响。append 是否分配新数组取决于容量，不能凭变量名判断是否独立。需要独立可修改的元素存储时新建切片并 copy；若元素本身含指针，copy 仍不是任意对象图的深拷贝。预期应能解释示例中共享修改和独立副本的区别。</p></details><h2 id="nil-review" tabindex="-1">为什么 interface nil 判断失败 <a class="header-anchor" href="#nil-review" aria-label="Permalink to &quot;为什么 interface nil 判断失败 {#nil-review}&quot;">​</a></h2><p>题目：一个具体指针为 nil，把它赋给接口后，接口是否等于 nil？返回 error 时应如何避免这个问题？先完成<a href="/programming/go/base/intermediate/functions#interface-nil">接口 nil 实验</a>。</p><details class="details custom-block"><summary>参考解法</summary><p>接口包含动态类型和动态值。有具体指针类型但值为 nil 的接口，整体仍不为 nil。表示成功时返回字面 nil，而不是携带 nil 指针的 error 接口。预期能说明“具体指针 nil”和“接口 nil”为什么不同；不能靠打印外观判断。</p></details><h2 id="cancel-review" tabindex="-1">context 取消会结束 goroutine 吗 <a class="header-anchor" href="#cancel-review" aria-label="Permalink to &quot;context 取消会结束 goroutine 吗 {#cancel-review}&quot;">​</a></h2><p>题目：消费者提前退出，生产者阻塞在发送上；只调用 cancel 是否足够？给出退出路径，再核对<a href="/programming/go/base/intermediate/engineering#cancel">取消与完成通知</a>。</p><details class="details custom-block"><summary>参考解法</summary><p>取消是通知，不会强制杀死 goroutine。阻塞发送处需要通过 select 同时监听 ctx.Done；收到取消后返回，调用者等待完成通知，才能证明工作已经结束。预期程序不会依赖 sleep 猜测退出时间。共享状态另需同步，context 本身不消除数据竞争。</p></details><h2 id="transaction-review" tabindex="-1">事务失败时哪些数据应该回滚 <a class="header-anchor" href="#transaction-review" aria-label="Permalink to &quot;事务失败时哪些数据应该回滚 {#transaction-review}&quot;">​</a></h2><p>题目：更新任务状态与写入状态变更记录属于一个业务操作，插入 changes 失败时，能否留下更新后的任务状态？在<a href="/programming/go/plus/practice/api#transaction">项目事务测试</a>中找出失败注入和持久化断言。records 保存学习心得，是独立操作，不属于这里的状态变更事务。</p><details class="details custom-block"><summary>参考解法</summary><p>更新 tasks 与插入 changes 应在同一事务内完成，两步都成功才提交。预期 changes 插入失败后任务状态回滚，状态变更记录数也不增加。事务外执行其中一步、忽略 Commit 错误或只检查 HTTP 状态，都不能证明数据库状态正确。核对项目中的 TestStatusRollback，而不是学习心得 records 的创建测试。</p></details><h2 id="evidence" tabindex="-1">用项目证据组织面试回答 <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;用项目证据组织面试回答 {#evidence}&quot;">​</a></h2><p>选一个问题，按“结论 → 适用条件 → 最小实验 → 失败情形 → 项目中的验证”回答。自测标准是能预测输出、能解释错误结果、能指出验证位置；只记住术语不算通过。答错时回到同一正文，不另抄一份答案笔记。</p><p>文件持久化练习见<a href="/programming/go/plus/practice/task-cli#exercise">任务工具</a>，服务实践见<a href="/programming/go/plus/practice/api">Gin 与 SQLite</a>。需要按顺序复习时选<a href="/topics/go/?route=go-review">核心机制复习路线</a>。更广的历史面试资料仍可从“面试与复习”进入，其覆盖范围不等于本批已经逐例验证的能力。</p><p>核对依据与完整示例在上述共用正文；语义依据：<a href="https://go.dev/ref/spec" target="_blank" rel="noopener noreferrer">Go 规范</a>、<a href="https://pkg.go.dev/context" target="_blank" rel="noopener noreferrer">context</a>、<a href="https://go.dev/doc/database/execute-transactions" target="_blank" rel="noopener noreferrer">database/sql 事务</a>。</p>',18)])])}const u=a(o,[["render",t]]);export{m as __pageData,u as default};
